"""Search Insert Position — lower bound.

The loop exits with `lo` sitting on the first index whose value is >= target,
which is exactly the insertion point.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo
